CREATE TABLE qb_papers(id TEXT PRIMARY KEY,year INTEGER NOT NULL,session TEXT,title TEXT NOT NULL,exam_code TEXT NOT NULL);
CREATE TABLE qb_documents(id TEXT PRIMARY KEY,paper_id TEXT NOT NULL REFERENCES qb_papers(id),role TEXT NOT NULL,name TEXT NOT NULL,mime_type TEXT NOT NULL,sha256 TEXT NOT NULL,storage_key TEXT NOT NULL,provenance TEXT NOT NULL,parent_sha256 TEXT,UNIQUE(paper_id,role,sha256));
CREATE TABLE qb_document_pages(document_id TEXT REFERENCES qb_documents(id),page_no INTEGER NOT NULL CHECK(page_no>0),raw_markdown TEXT NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(document_id,page_no));
CREATE TABLE qb_processing_runs(id TEXT PRIMARY KEY,paper_id TEXT REFERENCES qb_papers(id),method TEXT NOT NULL,producer TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE qb_batches(id TEXT PRIMARY KEY,paper_id TEXT NOT NULL REFERENCES qb_papers(id),fingerprint TEXT NOT NULL UNIQUE,revision INTEGER NOT NULL DEFAULT 0,payload TEXT NOT NULL,diagnostics TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE qb_batch_items(batch_id TEXT REFERENCES qb_batches(id),question_version_id TEXT NOT NULL,PRIMARY KEY(batch_id,question_version_id));
CREATE TABLE qb_paper_versions(id TEXT PRIMARY KEY,paper_id TEXT NOT NULL REFERENCES qb_papers(id),version INTEGER NOT NULL,previous_id TEXT REFERENCES qb_paper_versions(id),fingerprint TEXT NOT NULL,revision_note TEXT NOT NULL,UNIQUE(paper_id,version));
CREATE TABLE qb_sections(id TEXT PRIMARY KEY,paper_version_id TEXT NOT NULL REFERENCES qb_paper_versions(id),parent_id TEXT REFERENCES qb_sections(id),label TEXT NOT NULL,sort_order INTEGER NOT NULL,instruction TEXT NOT NULL);
CREATE TABLE qb_question_types(id TEXT PRIMARY KEY,label TEXT NOT NULL,component TEXT NOT NULL,response_type TEXT NOT NULL);
CREATE TABLE qb_questions(id TEXT PRIMARY KEY,paper_id TEXT NOT NULL REFERENCES qb_papers(id),node_key TEXT NOT NULL,UNIQUE(paper_id,node_key));
CREATE TABLE qb_question_versions(id TEXT PRIMARY KEY,question_id TEXT NOT NULL REFERENCES qb_questions(id),version INTEGER NOT NULL,type_id TEXT NOT NULL REFERENCES qb_question_types(id),original_label TEXT NOT NULL,sort_order INTEGER NOT NULL,text TEXT NOT NULL,options TEXT NOT NULL,response_type TEXT NOT NULL,annotations TEXT NOT NULL,fingerprint TEXT NOT NULL,payload TEXT NOT NULL,UNIQUE(question_id,version));
CREATE TABLE qb_materials(id TEXT PRIMARY KEY,paper_id TEXT NOT NULL REFERENCES qb_papers(id));
CREATE TABLE qb_material_versions(id TEXT PRIMARY KEY,material_id TEXT NOT NULL REFERENCES qb_materials(id),version INTEGER NOT NULL,kind TEXT NOT NULL,text TEXT NOT NULL,payload TEXT NOT NULL,fingerprint TEXT NOT NULL,UNIQUE(material_id,version));
CREATE TABLE qb_material_members(material_version_id TEXT REFERENCES qb_material_versions(id),question_version_id TEXT REFERENCES qb_question_versions(id),sort_order INTEGER NOT NULL,PRIMARY KEY(material_version_id,question_version_id));
CREATE TABLE qb_paper_items(paper_version_id TEXT REFERENCES qb_paper_versions(id),question_version_id TEXT REFERENCES qb_question_versions(id),section_id TEXT REFERENCES qb_sections(id),sort_order INTEGER NOT NULL,PRIMARY KEY(paper_version_id,question_version_id));
CREATE TABLE qb_assets(id TEXT PRIMARY KEY,sha256 TEXT NOT NULL UNIQUE,storage_key TEXT NOT NULL,mime_type TEXT NOT NULL,provenance TEXT NOT NULL);
CREATE TABLE qb_asset_links(asset_id TEXT REFERENCES qb_assets(id),question_version_id TEXT REFERENCES qb_question_versions(id),caption TEXT NOT NULL,PRIMARY KEY(asset_id,question_version_id));
CREATE TABLE qb_evidence_spans(id TEXT PRIMARY KEY,document_id TEXT NOT NULL,page_no INTEGER NOT NULL,start INTEGER NOT NULL CHECK(start>=0),end INTEGER NOT NULL CHECK(end>start),quote TEXT NOT NULL,role TEXT NOT NULL,FOREIGN KEY(document_id,page_no) REFERENCES qb_document_pages(document_id,page_no));
CREATE TABLE qb_issues(id TEXT PRIMARY KEY,batch_id TEXT REFERENCES qb_batches(id),question_version_id TEXT REFERENCES qb_question_versions(id),code TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('info','warning','blocking')),status TEXT NOT NULL CHECK(status IN ('open','resolved')),payload TEXT NOT NULL);
CREATE TABLE qb_corrections(id TEXT PRIMARY KEY,batch_id TEXT REFERENCES qb_batches(id),question_version_id TEXT REFERENCES qb_question_versions(id),before_text TEXT NOT NULL,after_text TEXT NOT NULL,reason TEXT NOT NULL,evidence_ids TEXT NOT NULL);
CREATE TABLE qb_reference_entries(id TEXT PRIMARY KEY,paper_id TEXT REFERENCES qb_papers(id),kind TEXT NOT NULL,original_label TEXT NOT NULL,text TEXT NOT NULL,evidence_ids TEXT NOT NULL);
CREATE TABLE qb_answer_sets(id TEXT PRIMARY KEY,question_version_id TEXT NOT NULL REFERENCES qb_question_versions(id),version INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('missing','mapped','conflicting','unusable','adopted')),adopted_value TEXT,payload TEXT NOT NULL,UNIQUE(question_version_id,version));
CREATE TABLE qb_answer_candidates(answer_set_id TEXT REFERENCES qb_answer_sets(id),reference_id TEXT REFERENCES qb_reference_entries(id),value TEXT NOT NULL,PRIMARY KEY(answer_set_id,reference_id));
CREATE TABLE qb_explanations(id TEXT PRIMARY KEY,question_version_id TEXT REFERENCES qb_question_versions(id),reference_id TEXT NOT NULL REFERENCES qb_reference_entries(id));
CREATE TABLE qb_catalog_state(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL);
INSERT INTO qb_catalog_state VALUES(1,0);
CREATE TABLE qb_knowledge_points(id TEXT PRIMARY KEY,subject TEXT NOT NULL,parent_id TEXT REFERENCES qb_knowledge_points(id),name TEXT NOT NULL,name_fr TEXT NOT NULL,definition TEXT NOT NULL,inclusions TEXT NOT NULL,exclusions TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('candidate','active','inactive','merged')),merged_into TEXT REFERENCES qb_knowledge_points(id),revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE qb_knowledge_aliases(normalized TEXT PRIMARY KEY,knowledge_id TEXT NOT NULL REFERENCES qb_knowledge_points(id),name TEXT NOT NULL);
CREATE TABLE qb_knowledge_closure(ancestor_id TEXT REFERENCES qb_knowledge_points(id),descendant_id TEXT REFERENCES qb_knowledge_points(id),distance INTEGER NOT NULL,PRIMARY KEY(ancestor_id,descendant_id));
CREATE TABLE qb_knowledge_relations(id TEXT PRIMARY KEY,from_id TEXT NOT NULL REFERENCES qb_knowledge_points(id),to_id TEXT NOT NULL REFERENCES qb_knowledge_points(id),kind TEXT NOT NULL CHECK(kind IN ('prerequisite','contrast','combination')),signal TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('candidate','checked')),revision INTEGER NOT NULL);
CREATE TABLE qb_method_patterns(id TEXT PRIMARY KEY,primary_id TEXT REFERENCES qb_knowledge_points(id),name TEXT NOT NULL,trigger_text TEXT NOT NULL,steps TEXT NOT NULL,boundary TEXT NOT NULL);
CREATE TABLE qb_analysis_versions(id TEXT PRIMARY KEY,question_version_id TEXT NOT NULL REFERENCES qb_question_versions(id),answer_set_id TEXT REFERENCES qb_answer_sets(id),catalog_revision INTEGER NOT NULL,payload TEXT NOT NULL,fingerprint TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE qb_classification_sets(id TEXT PRIMARY KEY,question_version_id TEXT NOT NULL REFERENCES qb_question_versions(id),analysis_id TEXT NOT NULL REFERENCES qb_analysis_versions(id),catalog_revision INTEGER NOT NULL,method_id TEXT REFERENCES qb_method_patterns(id),basis TEXT NOT NULL,fingerprint TEXT NOT NULL);
CREATE TABLE qb_question_knowledge(classification_id TEXT REFERENCES qb_classification_sets(id),knowledge_id TEXT REFERENCES qb_knowledge_points(id),role TEXT NOT NULL CHECK(role IN ('primary','auxiliary')),PRIMARY KEY(classification_id,knowledge_id));
CREATE UNIQUE INDEX qb_one_primary ON qb_question_knowledge(classification_id) WHERE role='primary';
CREATE INDEX qb_knowledge_lookup ON qb_question_knowledge(knowledge_id,role,classification_id);
CREATE INDEX qb_question_type ON qb_question_versions(type_id,question_id);
CREATE TABLE qb_review_events(id INTEGER PRIMARY KEY,question_version_id TEXT NOT NULL REFERENCES qb_question_versions(id),target_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('content','classification','human')),decision TEXT NOT NULL,actor_type TEXT NOT NULL CHECK(actor_type IN ('ai','program','human','legacy')),actor TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX qb_review_latest ON qb_review_events(question_version_id,kind,id);
CREATE TABLE qb_releases(id TEXT PRIMARY KEY,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE qb_release_items(release_id TEXT REFERENCES qb_releases(id),question_version_id TEXT REFERENCES qb_question_versions(id),answer_set_id TEXT REFERENCES qb_answer_sets(id),classification_id TEXT REFERENCES qb_classification_sets(id),PRIMARY KEY(release_id,question_version_id));
CREATE TABLE qb_effective_items(question_id TEXT PRIMARY KEY REFERENCES qb_questions(id),question_version_id TEXT NOT NULL REFERENCES qb_question_versions(id),answer_set_id TEXT REFERENCES qb_answer_sets(id),classification_id TEXT REFERENCES qb_classification_sets(id),release_id TEXT REFERENCES qb_releases(id),content_status TEXT NOT NULL CHECK(content_status IN ('passed','returned')));
CREATE TABLE qb_legacy_mappings(import_id TEXT NOT NULL,legacy_question_id TEXT NOT NULL,source_id TEXT NOT NULL,question_version_id TEXT REFERENCES qb_question_versions(id),content_fingerprint TEXT NOT NULL,PRIMARY KEY(import_id,legacy_question_id));
CREATE TABLE qb_duplicate_pairs(left_id TEXT REFERENCES qb_questions(id),right_id TEXT REFERENCES qb_questions(id),status TEXT NOT NULL CHECK(status IN ('candidate','checked')),basis TEXT NOT NULL,PRIMARY KEY(left_id,right_id),CHECK(left_id<right_id));
CREATE TRIGGER qb_raw_page_update BEFORE UPDATE ON qb_document_pages BEGIN SELECT RAISE(ABORT,'raw pages are immutable'); END;
CREATE TRIGGER qb_raw_page_delete BEFORE DELETE ON qb_document_pages BEGIN SELECT RAISE(ABORT,'raw pages are immutable'); END;
CREATE TRIGGER qb_question_version_update BEFORE UPDATE ON qb_question_versions BEGIN SELECT RAISE(ABORT,'question versions are immutable'); END;
